# Define a function to generate regions for a given input
def analyze_demo(input_grid):
    rows = len(input_grid)
    cols = len(input_grid[0])

    # Find anchor columns (columns with 8s in all rows)
    anchor_cols = []
    for c in range(cols):
        all_8 = all(input_grid[r][c] == 8 for r in range(rows))
        if all_8:
            anchor_cols.append(c)

    print(f"Anchor columns: {anchor_cols}")

    # Find row bands (consecutive rows before/after anchor rows)
    anchor_rows = []
    for r in range(rows):
        if input_grid[r] == [8]*cols:
            anchor_rows.append(r)
    print(f"Anchor (full border) rows: {anchor_rows}")

    # Find special cells (non-0, non-8)
    special = []
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] not in [0, 8]:
                special.append((r, c, input_grid[r][c]))

    print(f"Special cells: {special}")

    return input_grid

