def transform_v4(input_grid):
    rows = len(input_grid)
    cols = len(input_grid[0])

    anchor_rows = sorted([r for r in range(rows) if input_grid[r] == [8] * cols])
    anchor_cols = sorted([c for c in range(cols) if all(input_grid[r][c] == 8 for r in range(rows))])

    row_bands = []
    prev = 0
    for ar in anchor_rows:
        if ar > prev:
            row_bands.append((prev, ar - 1))
        prev = ar + 1
    if prev < rows:
        row_bands.append((prev, rows - 1))

    col_bands = []
    prev = 0
    for ac in anchor_cols:
        if ac > prev:
            col_bands.append((prev, ac - 1))
        prev = ac + 1
    if prev < cols:
        col_bands.append((prev, cols - 1))

    band_bits = {}
    for r in range(rows):
        for c in range(cols):
            v = input_grid[r][c]
            if v not in [0, 8]:
                rb_idx = None
                for i, (start, end) in enumerate(row_bands):
                    if start <= r <= end:
                        rb_idx = i
                        break
                if rb_idx is None:
                    rb_idx = 0
                bc_idx = None
                for i, (start, end) in enumerate(col_bands):
                    if start <= c <= end:
                        bc_idx = i
                        break
                if bc_idx is None:
                    bc_idx = 0

                if (rb_idx, bc_idx) not in band_bits:
                    band_bits[(rb_idx, bc_idx)] = [False, False]
                if v == 2:
                    band_bits[(rb_idx, bc_idx)][0] = True
                elif v == 3:
                    band_bits[(rb_idx, bc_idx)][1] = True

    output = [input_grid[i][:] for i in range(rows)]

    for (rb, bc), (has2, has3) in band_bits.items():
        if has2 and has3:
            fill = 6
        elif has2:
            fill = 2
        elif has3:
            fill = 3
        else:
            fill = 0

        row_start, row_end = row_bands[rb]
        col_start, col_end = col_bands[bc]

        for r in range(row_start, row_end + 1):
            for c in range(col_start, col_end + 1):
                if output[r][c] == 8:
                    continue
                output[r][c] = fill

    return output, row_bands, col_bands, band_bits

