def solve_transform(input_grid):
    """
    THE CORRECT TRANSFORMATION:
    1. Find anchors (rows/cols of all 8s)
    2. Create row bands and col bands from anchors
    3. Count which band cells have special values (non-0, non-8)
    4. For each row band that has multiple bands with the same non-zero value:
       - Fill those band cells with that value
       - Put 6 in the FIRST empty band between them (counting left to right)
    5. For each row band with a single band having non-zero value:
       - Fill that band cell with the value
    """
    rows = len(input_grid)
    cols = len(input_grid[0])

    # Get anchors
    anchor_rows = sorted(set(r for r in range(rows) if all(input_grid[r][c] == 8 for c in range(cols))))
    anchor_cols = sorted(set(c for c in range(cols) if all(input_grid[r][c] == 8 for r in range(rows))))

    # Create bands
    row_bands = []
    prev = 0
    for ar in anchor_rows:
        if ar > prev:
            row_bands.append((prev, ar - 1))
        prev = ar + 1
    if prev < rows:
        row_bands.append((prev, rows - 1))

    col_bands = []
    prev = 0
    for ac in anchor_cols:
        if ac > prev:
            col_bands.append((prev, ac - 1))
        prev = ac + 1
    if prev < cols:
        col_bands.append((prev, cols - 1))

    # Initialize output
    output = [[0] * cols for _ in range(rows)]
    for r in anchor_rows:
        output[r] = [8] * cols
    for c in anchor_cols:
        for r in range(rows):
            output[r][c] = 8

    # Count values per (row_band_idx, col_band_idx)
    band_value_counts = {}  # (rb, cb) -> list of values
    for r in range(rows):
        for c in range(cols):
            v = input_grid[r][c]
            if v in [0, 8]:
                continue
            rb_idx = next(i for i, band in enumerate(row_bands) if band[0] <= r <= band[1])
            cb_idx = next(i for i, band in enumerate(col_bands) if band[0] <= c <= band[1])
            key = (rb_idx, cb_idx)
            if key not in band_value_counts:
                band_value_counts[key] = []
            band_value_counts[key].append(v)

    # Filter to keep only non-zero values
    band_values = {}
    for key, vals in band_value_counts.items():
        unique_nonzero = list(set(v for v in vals if v not in [0, 8]))
        if unique_nonzero:
            # Determine what to store - count +6 logic
            has_six = len(unique_nonzero) > 1  # more than one non-zeros
            band_values[key] = unique_nonzero

    # Now fill - for each row band, process col bands
    for rb_idx in range(len(row_bands)):
        # Get all (rb_idx, cb_idx) with values
        row_band_items = [(cb_idx, v) for cb_idx, v_list in band_values.items() 
                          if v_list is not None and v_list[0] not in [0, 8] 
                          and (rb_idx, cb_idx) in band_value_counts and len(set(v for v in band_value_counts[(rb_idx, cb_idx)] if v not in [0, 8])) > 0]

        # Count which col bands have which values
        col_band_value_map = {}  # cb_idx -> value (or list of values)
        for cb_idx in range(len(col_bands)):
            key = (rb_idx, cb_idx)
            if key in band_value_counts:
                vals = [v for v in band_value_counts[key] if v not in [0, 8]]
                if len(set(vals)) == 1 and len(vals) >= 1:
                    col_band_value_map[cb_idx] = vals[0]

        # For each row band, detect same-value merges
        # Value X at cols C1, C2, ... -> fill all empty cols between with X, put 6 at first empty
        for val in [2, 3]:
            col_bands_with_val = sorted([cb for cb, v in col_band_value_map.items() if v == val])
            if len(col_bands_with_val) >= 2:
                # Fill all bands between first and last
                for cb_idx in range(col_bands_with_val[0], col_bands_with_val[-1] + 1):
                    output_band_start = col_bands[cb_idx][0]
                    output_band_end = col_bands[cb_idx][1]
                    for r in range(row_bands[rb_idx][0], row_bands[rb_idx][1] + 1):
                        for c in range(output_band_start, output_band_end + 1):
                            if c not in col_bands_with_val:  # only fill empty ones
                                output[r][c] = val

                # Also fill filled bands and add 6 at first empty
                for cb_idx in col_bands_with_val:
                    output_band_start = col_bands[cb_idx][0]
                    output_band_end = col_bands[cb_idx][1]
                    for r in range(row_bands[rb_idx][0], row_bands[rb_idx][1] + 1):
                        for c in range(output_band_start, output_band_end + 1):
                            output[r][c] = val

                # Put 6 at first empty
                first_empty = None
                for cb_idx in range(col_bands_with_val[0], col_bands_with_val[-1] + 1):
                    if cb_idx not in col_bands_with_val:
                        first_empty = cb_idx
                        break
                if first_empty is not None:
                    output_band_start = col_bands[first_empty][0]
                    output_band_end = col_bands[first_empty][1]
                    for r in range(row_bands[rb_idx][0], row_bands[rb_idx][1] + 1):
                        for c in range(output_band_start, output_band_end + 1):
                            output[r][c] = 6
        # Handle single bands
        for val in [2, 3]:
            col_bands_with_val = [cb for cb, v in col_band_value_map.items() if v == val]
            for cb_idx in col_bands_with_val:
                output_band_start = col_bands[cb_idx][0]
                output_band_end = col_bands[cb_idx][1]
                for r in range(row_bands[rb_idx][0], row_bands[rb_idx][1] + 1):
                    for c in range(output_band_start, output_band_end + 1):
                        output[r][c] = val

    return output

